package com.supportsphere.dao; import com.supportsphere.model.*; import com.supportsphere.util.*; import java.sql.*; import java.time.*; import java.util.*;
public class VolunteerDAO implements DAO<Volunteer,Integer>{
 public Optional<Volunteer> findById(Integer id)throws Exception{String q="SELECT u.*,vp.experience_years,vp.availability_start,vp.availability_end,vp.verification_status,vp.rating,vp.rating_count FROM users u JOIN volunteer_profiles vp ON vp.volunteer_id=u.user_id WHERE u.user_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(c,r)):Optional.empty();}}}
 public List<Volunteer> findAll()throws Exception{List<Volunteer>x=new ArrayList<>();String q="SELECT u.*,vp.experience_years,vp.availability_start,vp.availability_end,vp.verification_status,vp.rating,vp.rating_count FROM users u JOIN volunteer_profiles vp ON vp.volunteer_id=u.user_id WHERE u.role='VOLUNTEER' ORDER BY vp.rating DESC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())x.add(map(c,r));}return x;}
 public void updateVerification(int id,String status)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE volunteer_profiles SET verification_status=? WHERE volunteer_id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}}
 public void updateRating(int id,int rating)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE volunteer_profiles SET rating=((rating*rating_count)+?)/(rating_count+1),rating_count=rating_count+1 WHERE volunteer_id=?")){p.setInt(1,rating);p.setInt(2,id);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}}
 private Volunteer map(Connection c,ResultSet r)throws Exception{Volunteer v=new Volunteer(r.getInt("user_id"),r.getString("name"),r.getString("email"),r.getString("phone"),r.getString("area"),r.getString("city"),r.getString("landmark"));v.setExperienceYears(r.getInt("experience_years"));v.setAvailabilityStart(r.getTime("availability_start").toLocalTime());v.setAvailabilityEnd(r.getTime("availability_end").toLocalTime());v.setVerificationStatus(r.getString("verification_status"));v.setRating(r.getDouble("rating"));v.setRatingCount(r.getInt("rating_count"));try(PreparedStatement p=c.prepareStatement("SELECT s.skill_name FROM skills s JOIN volunteer_skills vs ON vs.skill_id=s.skill_id WHERE vs.volunteer_id=?")){p.setInt(1,v.getUserId());try(ResultSet x=p.executeQuery()){while(x.next())v.getSkills().add(x.getString(1));}}return v;}
}
